    &\coloneqq B(\mc{M}(c,-), \mc{D}, \mc{N}(-,e))
  \end{align*}

\label{def:shadow}
  Let $\mc{B}$ be a bicategory.  A \textbf{shadow functor} for $\mc{B}$
  consists of functors
  \[
   \shvar{}{-}\colon  \mc{B}(C,C) \to \mathbf{T}
  \]
  for each object $C$ of $\mc{B}$ and some fixed category $\mathbf{T}$, equipped
  with a natural isomorphism
  \[
   \theta\colon \shvar{}{M\odot N}\xrightarrow{\cong} \shvar{}{N\odot M}
  \]
  for $M\in \mc{B}(C, D)$ and $N\in \mc{B}(D, C)$ such that the following
  diagrams commute whenever they make sense:
  \[\xymatrix{
    \shvar{}{(M\odot N)\odot P} \ar[r]^\theta \ar[d]_{\shvar{}{a}} &
    \shvar{}{P \odot (M\odot N)} \ar[r]^{\shvar{}{a}} &
    \shvar{}{(P\odot M) \odot N}
    \\
    \shvar{}{M\odot (N\odot P)} \ar[r]^\theta 
    & \shvar{}{(N\odot P)\odot M} \ar[r]^{\shvar{}{a}} 
   & \shvar{}{N\odot (P\odot M)}\ar[u]_\theta 
  }\]
  \[\xymatrix{
    \shvar{}{M\odot U_C} \ar[r]^\theta \ar[dr]_{\shvar{}{r}} &
    \shvar{}{U_C\odot M} \ar[d]^{\shvar{}{l}} \ar[r]^\theta &
    \shvar{}{M\odot U_C} \ar[dl]^{\shvar{}{r}}
    \\
    &\shvar{}{M}}\]

\[
   \shvar{}{-}\colon  \mc{B}(C,C) \to \mathbf{T}
  \]

\[
   \theta\colon \shvar{}{M\odot N}\xrightarrow{\cong} \shvar{}{N\odot M}
  \]

\[\xymatrix{
    \shvar{}{(M\odot N)\odot P} \ar[r]^\theta \ar[d]_{\shvar{}{a}} &
    \shvar{}{P \odot (M\odot N)} \ar[r]^{\shvar{}{a}} &
    \shvar{}{(P\odot M) \odot N}
    \\
    \shvar{}{M\odot (N\odot P)} \ar[r]^\theta 
    & \shvar{}{(N\odot P)\odot M} \ar[r]^{\shvar{}{a}} 
   & \shvar{}{N\odot (P\odot M)}\ar[u]_\theta 
