\cite{p:thesis}\label{defn:trace}
  Let $\mc{B}$ be a bicategory with a shadow functor and $(M,N)$ be a dual pair.
  The \textbf{trace} of a 2-cell $f\colon Q\odot M\rightarrow M\odot P$ is the composite:
  \[
   \shvar{}{Q}\cong \shvar{}{Q\odot U_C}\xrightarrow{\shvar{}{\id_Q\odot\eta}}
  \shvar{}{Q\odot M\odot N} \xrightarrow{\shvar{}{f\odot\id_N}}
  \shvar{}{M\odot P\odot N} \xrightarrow{\theta}
  \shvar{}{N\odot M\odot P} \xrightarrow{\shvar{}{\epsilon \odot \id_P}}
  \shvar{}{U_D\odot P}\cong   \shvar{}{P}.
  \]
The trace of a 2-cell $g\colon N\odot Q\to P\odot N$ is 
  \[
   \shvar{}{Q}\cong \shvar{}{U_C\odot Q}\xrightarrow{\shvar{}{\eta\odot\id_Q}}
  \shvar{}{M\odot N\odot Q} \xrightarrow{\shvar{}{\id_M\odot g}}
  \shvar{}{M\odot P\odot N} \xrightarrow{\theta}
  \shvar{}{P\odot N\odot M} \xrightarrow{\shvar{}{\id_P \odot \epsilon}}
    \shvar{}{P\odot U_D}\cong   \shvar{}{P}.
  \]

\[
   \shvar{}{Q}\cong \shvar{}{Q\odot U_C}\xrightarrow{\shvar{}{\id_Q\odot\eta}}
  \shvar{}{Q\odot M\odot N} \xrightarrow{\shvar{}{f\odot\id_N}}
  \shvar{}{M\odot P\odot N} \xrightarrow{\theta}
  \shvar{}{N\odot M\odot P} \xrightarrow{\shvar{}{\epsilon \odot \id_P}}
  \shvar{}{U_D\odot P}\cong   \shvar{}{P}.
  \]

\[
   \shvar{}{Q}\cong \shvar{}{U_C\odot Q}\xrightarrow{\shvar{}{\eta\odot\id_Q}}
  \shvar{}{M\odot N\odot Q} \xrightarrow{\shvar{}{\id_M\odot g}}
  \shvar{}{M\odot P\odot N} \xrightarrow{\theta}
  \shvar{}{P\odot N\odot M} \xrightarrow{\shvar{}{\id_P \odot \epsilon}}
    \shvar{}{P\odot U_D}\cong   \shvar{}{P}.
  \]

\begin{gather*}
  \rsm{\eta}{M}{N}{Q}\colon Q\odot M\cong U_C\odot Q\odot M
  \xrightarrow{\eta\odot \id_Q\odot \id_M} 
  M\odot N\odot Q\odot M
 \\
  \rsm{\epsilon}{M}{N}{P}\colon M\odot P\odot N\odot M
  \xrightarrow{\id_M \odot \id_P \odot\epsilon}
  M\odot P\odot U_D\cong M\odot P
 \\
   \lsm{\eta}{M}{N}{Q} \colon N\odot Q\cong N\odot Q\odot U_C
  \xrightarrow{\id_N\odot \id_Q\odot \eta} N\odot Q\odot M\odot N
 \\
   \lsm{\epsilon}{M}{N}{P}\colon N\odot M\odot P\odot N
   \xrightarrow{\epsilon\odot \id_P \odot \id_N }
   U_D\odot P\odot N\cong P\odot N
\end{gather*}

\label{left_or_right_for_trace} 
If $(M,N)$ is a dual pair, the {\bf dual} of a map 
$g\colon N\odot Q\to P\odot N$, denoted $g^\star$, is the composite 
\begin{align*}
	Q\odot M\xrightarrow{\rsm{\eta}{M}{N}{Q}}
 	M\odot N\odot Q\odot M\xrightarrow{\id_M \odot g\odot \id_M}M\odot P\odot N\odot M
	\xrightarrow{\rsm{\epsilon}{M}{N}{P} }
	M\odot P
\end{align*}
Since $\mathrm{tr}(g)=\mathrm{tr}(g^\star)$ \cite[Prop.~7.6]{ps:bicat} we freely move between traces defined with respect to $M$ and those defined with respect to $N$.

Note that  $\rsm{\eta}{M}{N}{Q}$ is the dual of $\lsm{\eta}{M}{N}{Q}$,
$\rsm{\epsilon}{M}{N}{Q}$ is the dual of $\lsm{\epsilon}{M}{N}{Q}$,
and 
\begin{gather*}
	\shvar{}{Q}\xrightarrow{\mathrm{tr}\left(\rsm{\eta}{M}{N}{Q}\right)=\mathrm{tr}\left(\lsm{\eta}{M}{N}{Q}\right)} \shvar{}{N\odot Q\odot M}
	\quad \text{and } \quad 
	\shvar{}{M\odot P\odot N}\xrightarrow{\mathrm{tr}\left(\rsm{\epsilon}{M}{N}{P}\right)=\mathrm{tr}\left(\lsm{\epsilon}{M}{N}{P}\right)} \shvar{}{P}
\end{gather*}

\begin{align*}
	Q\odot M\xrightarrow{\rsm{\eta}{M}{N}{Q}}
 	M\odot N\odot Q\odot M\xrightarrow{\id_M \odot g\odot \id_M}M\odot P\odot N\odot M
	\xrightarrow{\rsm{\epsilon}{M}{N}{P} }
	M\odot P
\end{align*}

\begin{gather*}
	\shvar{}{Q}\xrightarrow{\mathrm{tr}\left(\rsm{\eta}{M}{N}{Q}\right)=\mathrm{tr}\left(\lsm{\eta}{M}{N}{Q}\right)} \shvar{}{N\odot Q\odot M}
	\quad \text{and } \quad 
	\shvar{}{M\odot P\odot N}\xrightarrow{\mathrm{tr}\left(\rsm{\epsilon}{M}{N}{P}\right)=\mathrm{tr}\left(\lsm{\epsilon}{M}{N}{P}\right)} \shvar{}{P}
\end{gather*}

\[
	\shvar{}{M\odot P\odot N}\xrightarrow{\sim}\shvar{}{P\odot N\odot M}\xrightarrow{\shvar{}{\id_P\odot \epsilon}} \shvar{}{P\odot U_D}\cong\shvar{}{P}
\]

