\label{defn:base_change_category}
 Let $F\colon  \mc{A} \to \mc{C}$ be a morphism in $\mathbf{Cat}(\mc{V})$, i.e. a functor of categories enriched in $\mc{V}$. Then there is an $(\mc{A}, \mc{C})$-bimodule $_F \mc{C}$ where the left action of $\mc{A}$ is given by
  \begin{align*}
  \mc{A}(a, a') \otimes ({_F \mc{C}})(a', c) 
   &= \mc{A}(a, a') \otimes \mc{C}(F(a'), c) 
  \\
  &\to \mc{C}(F(a), F(a')) \otimes \mc{C}(F(a'), c) \to \mc{C}(F(a), c) = {_F \mc{C}(a, c)} 
  \end{align*}
  There is a dual $(\mc{C}, \mc{A})$-bimodule that we denote $\mc{C}_F$.

\begin{align*}
  \mc{A}(a, a') \otimes ({_F \mc{C}})(a', c) 
   &= \mc{A}(a, a') \otimes \mc{C}(F(a'), c) 
  \\
  &\to \mc{C}(F(a), F(a')) \otimes \mc{C}(F(a'), c) \to \mc{C}(F(a), c) = {_F \mc{C}(a, c)} 
  \end{align*}

\cite[Appendix]{p:thesis}\cite[Lem.~7.6]{ps:indexed}\label{lem:base_change_euler}
\begin{enumerate}
  \item If $f\colon A\to C$ is a monoid homomorphism, $(_fC,C_f)$ is a dual pair.
  \item If $F\colon \sA\to \sC$ be a $\sV$-functor between $\sV$-categories, $({_F\sC},\sC_F)$ is a dual pair.
\end{enumerate}

For objects $a$ and $a'$ in $\mc{A}$, a choice for the   
coevaluation is
\begin{align*}
 {\sA}(a,a')\xrightarrow{F} \sC(F(a),F(a'))&\cong \sC(F(a),F(a'))\otimes 1_{\sV}
 \\
 &\to \sC(F(a),F(a'))\otimes\sC(F(a'),F(a'))\to \sC(F(a),-)\odot\sC(-,F(a')) 
\end{align*}

\begin{align*}
 {\sA}(a,a')\xrightarrow{F} \sC(F(a),F(a'))&\cong \sC(F(a),F(a'))\otimes 1_{\sV}
 \\
 &\to \sC(F(a),F(a'))\otimes\sC(F(a'),F(a'))\to \sC(F(a),-)\odot\sC(-,F(a')) 
\end{align*}

