  &\sC(c,c')
  \\
  \sC(c,F(-))\odot \sC(F(-),c') \ar@{.>}[ur]
}\]

\[
  \mc{A}^{\text{op}}\otimes \mc{B}\xrightarrow{F\otimes G}\mc{C}^{\text{op}}\otimes \mc{D}\xrightarrow{\mc{M}}\mc{V}
